import java.util.Scanner;
import java.text.DecimalFormat;

// Asks the user for a temperature in fahreinheit 
// and converts it to celsius.  Fractional numbers
// are nicely formatted.
// Author: Michael Hay
public class TempConverterFToC {
  public static void main(String[] args) {
    DecimalFormat fmtTemp = new DecimalFormat(".#");
    Scanner scan = new Scanner(System.in);
    double fahrenheit = scan.nextDouble();

    double celsius = (5.0 / 9) * (fahrenheit - 32);

    System.out.print(fmtTemp.format(fahrenheit));
    System.out.print(" degrees fahrenheit is ");
    fmtTemp.applyPattern(".##");
    System.out.print(fmtTemp.format(celsius));
    System.out.println(" degrees celsius.");
  }
}

