///

int primitiveGCD(int A, int B){
  int g;
  if (A < 0 || B < 0 ) return -1; /*error*/
  g = B;
  if (A < B){B = A; A = g; g = B;}
  /* if g is not a factor of either it will return true value and it will continue looping */
  while(A%g || B%g)g--;

  return g;
}

